const raw = String($input.first().json.data).replace(/^\uFEFF/, '');

// detecta delimitador pela primeira linha
const firstLine = raw.split(/\r?\n/)[0];
const delim = (firstLine.match(/;/g) || []).length > (firstLine.match(/,/g) || []).length ? ';' : ',';

function parseCSV(text, d) {
  const rows = [];
  let row = [], cur = '', q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) {
      if (c === '"' && text[i + 1] === '"') { cur += '"'; i++; }
      else if (c === '"') q = false;
      else cur += c;
    } else if (c === '"') q = true;
    else if (c === d) { row.push(cur); cur = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      row.push(cur); cur = '';
      if (row.some(v => v !== '')) rows.push(row);
      row = [];
    } else cur += c;
  }
  row.push(cur);
  if (row.some(v => v !== '')) rows.push(row);
  return rows;
}

// aceita "1.234,56", "R$ 1.234,56", "1234.56", "1,234.56", "1.500"
function toNumber(v) {
  if (v == null) return null;
  let s = String(v).trim().replace(/[^\d,.\-]/g, '');
  if (!s) return null;
  const lc = s.lastIndexOf(','), ld = s.lastIndexOf('.');
  if (lc > ld) s = s.replace(/\./g, '').replace(',', '.');      // pt-BR
  else if (lc === -1 && /^-?\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, ''); // 1.500 -> 1500
  else s = s.replace(/,/g, '');                                  // en-US
  const n = parseFloat(s);
  return Number.isNaN(n) ? null : n;
}

const norm = h => h.trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

const [header, ...lines] = parseCSV(raw, delim);
const cols = header.map(h => h.trim());
const idxMin = header.findIndex(h => norm(h) === 'minimo');

return lines.map(r => {
  const obj = {};
  cols.forEach((c, i) => (obj[c] = r[i] ?? ''));
  if (idxMin >= 0) obj[cols[idxMin]] = toNumber(r[idxMin]);
  return { json: obj };
});

const body = $('Webhook').first().json.body;
const clientes = Array.isArray(body) ? body : (body.clientes || []);
const opcoes = $('Code in JavaScript').all().map(i => i.json);

const norm = s => String(s ?? '').trim().toLowerCase();

// converte "R$ 5.000,00" ou 5000 em número
const num = v => {
  if (typeof v === 'number') return v;
  const s = String(v ?? '').replace(/[^\d,.-]/g, '');
  return parseFloat(s.includes(',') ? s.replace(/\./g, '').replace(',', '.') : s) || 0;
};

const brl = v => v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

const templates = {
  conservador: (n, s, lista) => `Olá, ${n}! Com seu saldo de ${s}, o foco é segurança e previsibilidade. Boas opções pra você: ${lista}.`,
  moderado:    (n, s, lista) => `Olá, ${n}! Com ${s}, dá pra equilibrar renda fixa e variável. Sugestões: ${lista}.`,
  arrojado:    (n, s, lista) => `Olá, ${n}! Com ${s}, você pode buscar maior retorno com ativos de risco. Sugestões: ${lista}.`,
};

return clientes.map(c => {
  const perfil = norm(c.perfil);
  const saldo = num(c.saldo);

  const lista = opcoes
    .filter(o => norm(o.perfil) === perfil && num(o.minimo) <= saldo)
    .map(o => `${o.produto} (rentabilidade: ${o.rentabilidade}, mínimo: ${brl(num(o.minimo))})`)
    .join('; ') || 'nenhuma opção disponível para o saldo atual';

  const gerar = templates[perfil] || (n => `Olá, ${n}!`);

  return { json: {
    nome: c.nome,
    email: c.email,
    perfil: c.perfil,
    saldo: brl(saldo),
    opcoes: lista,
    mensagem_estatica: gerar(c.nome, brl(saldo), lista),
  }};
});

